    "description": "• 你的牙齿或指甲变得长而尖锐，从而准备好发起酸蚀性的打击。对一个处于你周围5尺内的生物进行一次近战法术攻击。命中则目标受到1d10点强酸伤害。在你进行此攻击后，你的牙齿或指甲恢复正常。\r\n• 此法术的伤害在你达到5级（2d10），11级（3d10），和17级（4d10）时提高1d10点。",
    "classes": "德鲁伊",
