    "description": "• 你行动如风。在持续时间内，你的移动不会导致借机攻击。\r\n• 此外，在此法术结束前仅一次，你可以在自己的回合让自己的一次武器攻击检定获得优势。这次攻击若击中会造成额外1d8力场伤害。无论你是否击中，你的步行速度都会增加30尺，直到这个回合结束。",
