    "description": "选择范围内你能看见的一个生物，使其遭受一种魔法毒素的攻击。目标受到2d4点毒素伤害，并必须进行一次体质豁免。若豁免失败，则目标在法术持续时间内中毒。\r\n以这种方式中毒的生物，必须在它的每个回合结束时进行一次体质豁免。豁免失败则承受2d4点毒素伤害。若豁免检定成功，则法术在目标身上终止。\r\n法术次级复原术Lesser Restoration可以提前结束目标身上的此法术。\r\n升环施法效应：使用二环或更高法术位施展该法术时，你使用的法术位每比一环高一环，你便可以额外选择一个生物作为目标。",
    "classes": "德鲁伊、术士、法师、药剂师",
    "source": "德拉肯海姆"
