    "description": "命中时或失手时，那枚弹药（或武器本身）化为一束5尺宽的线状魔法能量，自你延展至武器的常规范围为止。此线状区域需包括此次攻击的原目标，线状区域内的所有生物都需要通过一次敏捷豁免检定，豁免失败将受到武器的正常伤害，豁免成功将受到一半伤害。\r\n升环施法。使用的法术位每比一环高1环，武器的伤害就增加1d8。",
