    "duration": "1分钟",
    "description": "一面高5尺、宽5尺、厚1尺的沙墙从地面升起，出现在施法距离内你能看到的一处未被占据的空间内。当处于墙体形态时，这些沙子的坚固程度等同于实心石头。这面墙的AC为13且具有10点生命值。将墙体生命值降至0会摧毁它，且根据DM裁定可能导致相连的墙体坍塌。你可以用一个动作提前终止该法术。当法术结束时，墙体会崩塌回归沙砾。\r\n如果你以仪式形式施展此法术，墙体会持续存在直到被摧毁或解消。",
