    "description": "你迅速长出茂密的叶状植被覆盖全身。施展此法术时，你可以选择植被是否具有其他特征，比如花朵或浆果。\r\n当你处于倒地且静止不动状态时，你与普通的灌木难以分辨。如果某个生物未曾观察到你移动或行动，它必须通过一次对抗你法术豁免DC的智力（调查）检定才能判断出你不是一株灌木。若要在被某个生物识破真身后重新伪装，你必须在该生物看不见你的情况下采取躲藏动作。\r\n在法术持续时间内，你可以使用动作制造并投掷松果、浆果或花苞。当你这样做时，对30尺内的一个生物进行一次远程法术攻击。命中时，目标受到1d6+你的施法关键属性调整值的钝击伤害。",
