    "castingTime": "动作",
    "range": "60尺",
    "components": "V/S",
    "material": "",
    "duration": "立即",
    "description": "你释放出一道耀眼的焰能爆。对施法距离内的一个目标发动一次远程法术攻击；结算该次攻击检定时目标无法从半身掩护和四分之三掩护中获益。若命中，则目标受到2d10光耀伤害。\r\n升环施法。你使用的法术位每比一环高一环，你便可额外发射一道焰能爆。你可以令这发新的焰能爆瞄准你原先的目标或是另一个目标。每道焰能爆都需要分别进行攻击。",
    "classes": "术士、法师",
    "source": "被遗忘的国度：费伦英雄"
