    "description": "你触碰至多四根非魔法箭矢或弩矢，将其插在位于你所处空间的地面上。直到法术结束为止，这些弹药不能被物理方法拔起，且当除你之外的生物第一次进入距弹药30尺内空间或在距弹药30尺内空间结束回合时，一枚弹药便会飞起攻击此生物。那名生物必须成功于一次敏捷豁免，否则受到2d4点穿刺伤害。那枚弹药随之被摧毁。当所有弹药都没有插在地面上时，法术终止。\r\n施展该法术时，你可以指定任意名你选择的生物，法术效应将无视他们。\r\n升环施法：使用的法术位每比二环高一环，可被影响的弹药数量就增加两枚。",
