    "material": "",
    "duration": "立即",
    "description": "你感测到施法距离范围内，且在你视觉线范围内的任何陷阱。该法术的目标“陷阱”包括任何创造意图是造成伤害或其他危害的物件或装置。因此该法术可以感测警报术Alarm和守卫刻文Glyph of Warding ，也可以发现某个陷坑型机械陷阱。不过它不能揭示地板的某处自然产生的脆弱点，或某处不稳定的天花板，又或是某个隐藏的陷坑。\r\n该法术只单纯揭示陷阱的存在而不能得知陷阱的位置。不过你可以知晓所感测到陷阱其能够构成危害的大致形式。",
    "classes": "牧师、德鲁伊、游侠",
    "source": "玩家手册"
