    "duration": "专注，至多10分钟",
    "description": "你在一只空手上召出一把火焰刀。该刀刃的尺寸和形状近似于一把弯刀并在法术持续时间内持续存在。当你放下刀刃时其将消失不见，但你可以用一个附赠动作重新将其唤出。\r\n你可以用一个魔法动作使用该火焰刀发动一次近战法术攻击。若命中，则目标受到3d6+你的施法属性调整值点火焰伤害。\r\n火焰刀提供半径10尺的明亮光照，以及额外10尺的微光光照。\r\n升环施法：使用的法术位每比二环高一环，此法术的伤害就增加1d6。",
