    "description": "你以魔法影响施法距离内一个你能看见的生物，并对其施以某种行动暗示（不超过25个词）。由你指定的受术目标必须能听到并理解你的话语。暗示必须听起来可行，也不明显涉及伤害目标及其盟友的内容。比如说，你可以说“把邪教的宝库钥匙找来，然后给我。”或者：“别打了，让图书馆保持安静，然后出去别回来。”\r\n目标必须成功通过一次感知豁免，否则在法术持续时间内陷入魅惑，若你或你的盟友对其造成伤害此法术将提前结束。被魅惑的生物会尽其所能地执行你所描述的行为。你所暗示的行为可能会在法术持续时间内始终一直进行，而如果你所暗示的活动可以用更短的时间完成，则此法术会在目标完成了你的要求后随即终止。",
