    "description": "• 在魔术大师、大冒险家吉姆• 达克马奇运用过的许多骗术中，“发光的旧硬币”是其中最为经典的。当你施法时，你将作为法术材料成分的硬币丢往法术距离内任意一点。这枚硬币将会像处于法术光亮术light影响一般闪闪发光。在硬币周围30尺内，你所能看到、并且由你选择的每一个生物必须通过一次感知豁免，否则将会在持续时间内被硬币所分心。在被分心时，生物在感知（察觉）检定和先攻检定中具有劣势。",
