    "description": "• 持续时间内，你能够感知到你周围30尺范围内的传送门，且不论那些传送门是否开启。\r\n• 如果你以此侦测到了传送门，你可以再用一个动作对其进行分析。为此，你需要用施法属性进行一次DC15的属性检定。检定成功时，你将会得知这个传送门背后的目的地是哪个位面，以及他需要什么样的传送门钥匙，那之后本法术结束。检定失败时，你将不会得知该传送门的任何情报，且直到你下次施展本法术前你都无法再次对其分析。\r\n• 本法术的侦测能力可以穿透大部分的障碍，但3尺厚的土木、1尺厚的岩石、1寸厚的常见金属、或薄薄一层铅都能阻挡本法术的侦测。",
