    "material": "",
    "duration": "专注,至多1小时",
    "description": "• 你轻弹手腕, 让你手中的一件物品消失。这件只有你能持握的，重量不超过五磅物件会被传送到一个异次元空间，它会在法术持续时间内一直停留在那里。\r\n• 直到法术结束为止, 你可以用你的动作将物件召唤到你空余的手中, 你也可以用一个动作将该物件返还至异次元空间处。 到法术结束时仍然存在在异次元空间的物品会出现在你的位置中，你的脚下。",
