    "description": "你对施法距离内一个你能看见的生物进行心灵猛击。目标必须进行一次智力豁免检定。豁免失败时，目标受到3d6心灵伤害，并且直到其下一回合结束前不能发动借机攻击。此外，该生物在其下一个回合内只能选择执行一个动作或一个附赠动作，但不能在一回合内同时执行以上两者。豁免成功时，目标仅受到一半伤害。 \r\n升环施法。你使用的法术位每比二环高一环，就能多选择一个生物作为目标。",
