    "description": "你创造出一股恐怖的力量，缓慢地从内部挤压目标。选择施法距离内一可见生物，掷2d6并记录掷出的总值。在你之后的每个回合开始时，再掷一次2d6并将掷出的数值加到总值上。\r\n\r\n-若总值大于目标的力量，则其基于力量的攻击检定具有劣势。\r\n-若总值大于目标的敏捷，则其速度减半，且针对它的攻击检定具有优势。\r\n-若总值大于目标的当前生命值，则目标会立即向内坍缩并死亡。",
