    "description": "你用一团毒素淤泥在法术持续时间内覆盖一片15尺宽的立方区域。该区域变为困难地形，并充满危险的毒气。一个进入该区域或在其中开始回合的生物必须进行一次体质豁免。若豁免失败，则该生物受到1d8点毒素伤害并直到它的下一个回合开始前陷入中毒状态。即使生物不用呼吸或屏住呼吸，依然会受到此法术影响。\r\n升环施法效应：使用三环或更高法术位施展该法术时，你使用的法术位每比二环高一环，法术的伤害就额外提升1d8。",
