    "description": "你召唤出一只巨大的虚体猿掌，它升起并试图抓住施法距离内你能看见的一个巨型或更小的地面生物。猿掌尝试擒抱目标，使用你的施法关键属性调整值进行擒抱检定。如果你在对抗中失败，猿掌消失，法术终止。\r\n被猿掌擒抱的目标在其每回合开始时受到1d8点暗蚀伤害。目标可以用其动作按正常规则尝试挣脱擒抱。当擒抱被解除时，猿掌消失，法术终止。\r\n升环施法。使用三环或更高法术位施展该法术时，你使用的法术位每比二环高一环，就可以额外选择一个目标，并为每个目标分别召唤一只猿掌。这种情况下，法术持续到最后一只猿掌消失为止。当你选择这些目标时，它们之间的距离必须在60尺以内。",
    "classes": "德鲁伊、游侠、术士",
    "source": "胧忆岛：蒿野物语"
