    "description": "你对施法距离内一个你可见的生物施加一首侵蚀心智的歌谣。如果该生物的智力为4或更高，则其必须进行一次智力豁免检定，豁免失败则其在持续时间内陷入魅惑状态。 \r\n以这种方式被魅惑期间，目标会被一首只有它能听见的、快速重复的民谣所折磨；它在其每个回合开始时受到1d6心灵伤害，并在感知（察觉）检定以及用于维持专注的体质豁免中具有劣势。目标在其每个回合结束时重复该豁免，豁免成功则终止自身该法术。 \r\n升环施法。使用的法术位每比二环高一环，伤害就增加1d6。",
