    "description": "你选择的一个目标必须进行一次感知豁免。若豁免失败，则你和目标之间会形成一条病态的绿色以太系链。每当你受到伤害时、每个被此链接的目标都会受到该伤害一半的暗蚀伤害。 以这种方式造成的伤害会在计算抗性或免疫后再应用。如果被系住的目标生命值数降为0，则其将不再受到此法术的影响。 以一个附赠动作，你可以将系链从一个倒下（此处指生命值为0或死亡）的敌人身上到另一个目标身上。新目标必须通过一次感知豁免，否则也会受到此法术的影响。一个目标只能有一条系链。\r\n升环施法。当你用四环或更高环阶的法术位施展该法术时，每2比环高2环，便可增加一条系链。",
