    "description": "当你站在河岸或其他水域的岸边时，你召唤一个摆渡灵魄和它的船，它会出现在施法距离内一处可见未占据空间里。当它的生命值降为0或法术结束时，灵魄就会消失。灵魄对你和你的同伴友好。你需为该生物投掷先攻，该生物有自己的回合。它能带你和本法术每环阶最多1名同伴穿过河流或水体（不需要你的任何动作）或沿着同一水域的其他地点。如果你不发出任何命令，它会保护自己免受敌对生物的攻击，否则不会采取任何动作。\r\n如果你的专注被打破，渡船和摆渡人不会消失。相反，你失去了对被召唤的灵魄的控制，它变得对你和你的同伴充满敌意，它可能会攻击你。一个不受控制的摆渡人不能被你解散，在你召唤它1小时后就会消失。DM掌握摆渡灵魄的数据（使用次级月魔Lesser Lunar Devil ，见第九章（翻译暂缺），或须魔Bearded Devil 的数据）。\r\n升环施法。当你用三环或更高环阶的法术位施展该法术时，船可以带你和你的同伴穿过一个位面边界进入以太位面，然后在另一处水体处离开（使用猬魔Barbed Devil的数据）。当你使用五环或更环阶的法术位施展此法术时，它可以穿越冥河River Styx，将你和你的同伴带到多元宇宙的远处（使用月魔Lunar Devil（见《万兽图志》）或骨魔Bone Devil 的数据）。\r\n译注：月魔数据卡见后文引用怪物或万兽图志",
    "classes": "牧师、法师",
    "source": "黯潮之书"
