    "description": "你召唤一群灵体小帮手，持续至法术结束。小帮手们看起来像是人工生命体或是其它由你选择的构装，但其不具备实体，亦无法被伤害。小帮手们视为具有对奥秘技能以及用来施展该法术的那套工匠工具的熟练项。\r\n若你正在制造一件物品，这些灵体小帮手整体可被视为一名协助者，减半你制作这件物品的时间。",
