    "duration": "专注，至多10分钟",
    "description": "你在施法距离内某处创造一个隐形的传感器，该处可以是你熟悉的地点（你曾到访过或看见过的地方），也可以是你不熟悉的显眼处（比如一扇门后，拐角位置或树林里）。这一无形体且不受伤害的传感器会在法术持续期间停留在该地。\r\n施展该法术时，你可以选择进行观察或是聆听。你可以通过传感器以所选的感官方式感测，如同你处在传感器所在的空间。你能够以一个附赠动作在观察和聆听之间切换。\r\n可以看见传感器的生物（例如一名生物受益于识破隐形See Invisibility或真实视觉 时）会看到传感器是一个拳头大小的发光球体。",
