    "description": "30尺锥状区域内的所有生物必须通过一次感知豁免，豁免失败者将丢弃其所有持握物，并在法术持续时间内陷入恐慌状态。\r\n以此法被恐慌的生物必须在自己回合中执行疾走动作，并以此寻找最安全的路线远离你，直至其无路可走为止。如果该生物结束其回合时位于一处使其视觉线中没有你的空间，则其可以再进行一次感知豁免，豁免成功则法术对该生物的效应终止。",
