    "material": "一小块纱布",
    "duration": "专注，至多1小时",
    "description": "在法术持续时间内，你将触碰到的一名自愿生物连同其穿着携带物一起转化为一团云雾。如果目标的生命值降至0或其用一个魔法动作终止其身上的法术效应，则该目标身上的法术终止。\r\n在该形态下，目标唯一的移动方式即是10尺的飞行速度，且可以悬浮。该目标可以进入并占据一个已有生物占据的空间。其拥有钝击、穿刺和挥砍伤害的抗性，其对倒地状态免疫，且进行的力量、敏捷、体质豁免具有优势。该目标可以穿过狭隙，但会将液态物质视为固体表面。\r\n云雾形态的目标不能讲话或操作物件，其随身携带或持握的物件不会掉落，也不能被使用或与之互动。另外，目标也不能攻击或施法。\r\n升环施法：使用的法术位每比三环高一环，你就可以额外再指定一名生物作为法术目标。",
    "classes": "术士、魔契师、法师、药剂师",
    "source": "玩家手册"
