    "description": "一匹拟真的大型马形生物出现在施法距离内你选择的一处地面上的未占据空间中。你决定该生物的样貌，且它装备着鞍座、嚼子和缰绳。这些随法术创造的装备一旦离开坐骑10尺即化作一阵烟消失不见。\r\n在法术持续时间内，你或者一名你指定的生物可以骑乘此坐骑。坐骑使用乘用马Riding Horse的数据（见附录B），不过其具有100尺速度，每小时可行进13里。法术终止时，坐骑会慢慢消失，骑手有1分钟的时间下马。坐骑受到伤害时，法术将提前终止。",
