    "duration": "立即",
    "description": "你向你所遇到过的或某人遇到过且向你描述的一个生物发送一小段二十五个词以内的信息。该生物将在心中听到你的信息，它可以认出你是发讯人（如果他认识你），还可以用同样的方式立即回复一条讯息。法术会让目标能够理解你短讯的信息。\r\n你的传讯可以跨越任意长的距离，甚至能跨越位面。但如果目标和你不在同一个存在位面，则短讯术有5%的概率无法到达。如果讯息没能传达，你将得知这一结果。\r\n在收到你的信息后，一个生物能够屏蔽你以这个法术再次对他发信的能力，持续8小时。如果你在这段时间内试图送出另一条信息，你会得知你的短讯被屏蔽，并且法术失败。",
