    "description": "你给周围30尺固定灵光范围内的植物赋予有限的知觉与活力，使其能够与你沟通和按你的简单命令行事。你可以向植物询问最近一日该法术区域内所发生的事，由此了解有关于曾路过这里的生物、天气和其他状况的信息。\r\n你可以让区域内因植物生长形成的困难地形（如灌木丛）在法术持续时间内变为普通地形。你也可以在法术持续时间内将有植物生长的普通地形变成困难地形。\r\n虽然该法术并不能让植物拔根而起或移动位置，但它们可以依你的意愿而活动自己的树枝、藤蔓和茎秆。\r\n如果法术区域内有一个植物生物，你可以如同有共同语言一般与其交流。",
    "classes": "吟游诗人、德鲁伊、游侠",
    "source": "玩家手册"
