    "duration": "专注，至多10分钟",
    "description": "在法术持续时间内，保护性的灵体环绕在你的周围15尺灵光范围内飞舞。如果你属于善良或中立阵营，则它们飘渺的身形看起来像是天使或精类生物（由你选择）。如果你属于邪恶阵营，则它们将形如邪魔。\r\n施展此法术时，你可以指定特定生物让其不受该法术影响。除此之外的生物在灵光区域内将受法术影响致速度被减半。当灵光进入一个生物的空间、一个生物进入灵光或在灵光内结束回合时，，其必须进行一次感知豁免。豁免失败将受到3d8点光耀伤害（如果你属于善良或中立）或3d8点黯蚀伤害（如果你属于邪恶），豁免成功则只受到一半伤害。一名生物一回合仅需进行一次该豁免。\r\n升环施法： 使用的法术位每比三环高一环，此法术的伤害就增加 1d8。",
    "classes": "牧师",
    "source": "玩家手册"
