    "description": "你以施法距离内一点为中心创造出一团半径 20 尺的黄色恶心气体云团球状区域。云团内形成重度遮蔽。云团会一直留在空中，直至法术持续时间结束或一阵强风（比如造风术Gust of Wind创造的强风）将其吹散为止。\r\n如果一个生物在其回合开始时位于云团内，则它必须成功通过一次体质豁免。否则将陷入中毒状态直到其当前回合结束。因此而陷入中毒状态期间，该生物无法执行动作或附赠动作。",
