    "description": "你的阴影环绕着的手可以吸取他人的生命力来为自己疗伤。对你触及范围内的一名生物进行一次近战法术攻击。若命中，则目标受到3d6点暗蚀伤害，而你则恢复数值等同于所造成暗蚀伤害一半的生命值。\r\n该法术终止前，你可以在你的每个回合内用魔法动作对相同或不同的生物进行一次这样的攻击。\r\n升环施法：使用的法术位每比三环高一环，此法术的伤害就提高1d6。",
