    "material": "",
    "duration": "专注,至多1小时",
    "description": "• 在法术持续时间内，你或一个施法距离内的可见生物获得对心灵伤害的抗性，同时在智力、感知和魅力豁免检定上具有优势。\r\n• 升环施法效应：使用4环或更高法术位施展该法术时，你使用的法术位每比3环高一环，就可以多选择一个生物作为目标。而各目标之间距离不能超过30尺。",
    "classes": "吟游诗人、术士、魔契师、法师、奇械师",
