    "material": "",
    "duration": "专注,至多1分钟",
    "description": "• 你接触一个可见生物的思想并迫使它进行一次智力豁免检定。免疫恐慌的生物自动通过此豁免。若豁免失败，目标失去从敌人中辨别友伴的能力，将所有可见的生物识别为敌人直到法术结束。每次目标受到伤害时它都可以重复进行此豁免，若成功将结束它对自己的效果。\r\n• 每当受影响的生物选择另一个生物作为目标时，它必在攻击、法术或其他可用能力的范围里，从所有可见目标中随机选择目标。如果一名敌人提供了借机攻击的机会给受术生物，生物必须进行攻击，只要它有能力这么做。",
    "classes": "吟游诗人、术士、魔契师、法师",
