    "description": "• 选择距离内你能看见的，位于地面上的一点。以该点为中心，20尺立方的空间内，一道翻滚的泥土和岩石流喷发而出。在该区域中的每个生物必须进行一次敏捷豁免检定。若未通过豁免，该生物受到3d12点钝击伤害，成功的豁免令上述伤害减半。此外，该区域的地面成为困难地形直到被清理。该区域每5平方尺的空间，若用手来清理至少需要1分钟时间。\r\n• 升环施法效应：当你使用4环或更高的法术位施放该法术时，使用的法术位每高一环，伤害便增加1d12。",
