    "duration": "1分钟",
    "description": "你的双臂会变成强有力的翅膀，你的手指变成长而优美的羽毛。此法术的效果持续1分钟，之后羽毛会逐渐脱落、当你的双臂恢复原状时，你会轻轻地漂浮到地面上。这个法术会给施法者带来以下增益：\r\n以一个附赠动作，你可以飞行至多等同于你移动速度两倍的距离。你必须在移动结束后着陆，不过在此法术生效时，你不会受到坠落伤害，因为你的羽毛手臂会将你轻轻的带到地面上。\r\n你可以用有力的羽臂将自己向上推，距离相当于你移动速度的一半。\r\n在你的回合中可以使用一次此效果，并且可以与普通跳跃同时使用。\r\n坠落时，你可以利用反作用力收紧双臂，在风中滑行。你可以向任何方向至多等同你移动速度的距离飞行，并选择落脚点。\r\n在进行跳远或跳高时，你在所有的运动检定中具有优势。跳跃前不需要移动10尺，跳远的距离是正常情况下的三倍。\r\n要使用此法术，你的双手必须必须没有持有盾牌和重型武器，也不能超载。",
