    "duration": "专注，至多10分钟",
    "description": "你将周围半径15尺，高15尺的区域笼罩在一个球形的点缀着微星的夜空中。暮色掩盖了你的盟友，却清晰地照亮了你的敌人。\r\n受此法术影响的区域会因魔法阴影处于轻微遮蔽，其中的小星座柔和地闪烁。除了这些星星之外，只有由三环或更高的法术产生的光才能照亮球内的任何区域。非魔法光照在球体内不起作用，所有其他形式的魔法光照只能在其5尺内提供微光光照。\r\n施放此法术时，你可以指定任意数量的生物在球体内被超自然的阴影遮蔽。被选择的生物在球体内时，在敏捷（隐匿）检定上具有优势，并可在任何时候尝试躲藏。在该法术范围外生物在对其感知（察觉）检定上具有劣势。\r\n该区域内的所有其他生物都会被微缩星星的光芒所晕眩，导致它在球体内部的所有察觉检定具有劣势。当这些生物首次进入法术区域，或在该区域开始回合时、其必须进行一次感知豁免，否则就会陷入目盲，直到其回合结束。",
