    "description": "你呼唤永荣者的力量，令自身获得洞察万物运动的伟大韵律。当你施展该法术时，掷两个d20，并记录掷出的结果。为每个骰子选择应用在攻击检定、技能检定或豁免检定中的一项。同一选项可以应用给多个骰子。在接下来的 24 小时内，你能将60尺内你可见的一名盟友或敌人的任意掷骰结果改为你记录的骰子之一，但被修改的结果与你记录骰子的检定类型必须相同（攻击检定，技能检定或豁免检定）。目标仍会在该数字上加上任何相关的调整值，但在其他情况下会将替换后的数字视为其掷出的数字。\r\n要如此做，你必须以你的反应出示你的圣徽，并唤起你所用能量所属永荣者的名字。你可以在攻击检定，技能检定或豁免检定掷出之后、但在事件结果确定之前如此做。法术会在24小时后结束，或者当两个骰子被消耗时法术提前结束。",
