    "description": "你将暗影物质绑定至一条附魔的妖精之路上，固定两点之间的道路，以抵御普通天气和世俗的变化，并在暗影潮汐中伸展和弯曲。这被称为暗影之路，它会受到正常的磨损，会被那些有工具的人破坏，也会被敌对力量的魔法破坏，比如解除魔法Dispel Magic 。\r\n如果你愿意，法术可以包含一个祷词或祭品作为关键词。这条道路的秘密允许任何知道并使用它的人在道路上添加一到两个效果，例如在道路上更快地行走（最高可达到通常允许的陆上速度的两倍）或锁定和解锁影域Shadow Realm之外的道路。那些不知道祷词、仪式或祭品的人不能从影域之外进入这条路。",
