    "description": "你和最多五个其他生物向妖精王庭的领主和女领主们敬酒。从以下祝酒词中选择之一，目标必须在施法过程中距离你10尺内。\r\n惺惺相惜Commiseration。施法者可以组建或加入一个鬼婆集会。在集会中，每个成员之间可以共享法术位。法术持续期间，鬼婆集会中一名成员知晓的法术所有成员都会知晓，并且可以使用任何共享的法术位施展。\r\n友谊Friendship。每个参加祝酒会的生物在法术持续时间内变成妖精生物，取代他们原来的生物类型，当他们处于影域或曙光之地Bright Lands时，他们的地位status*会增加 2d6。 （见第一章[不全书暂无]）\r\n畜牧Husbandry。在法术持续时间内，参与者可以与野兽交流，就像他们有共通的语言一样（尽管他们不会获得影响野兽的魔法能力）。\r\n噩梦Nightmares。 在法术持续时间内，生物首次靠近其中一名参与者30尺内时，它必须通过一次感知豁免，否则会在1分钟内对所有参与者恐慌。\r\n嬉戏Playfulness。 每个参与者都会长出翅膀，并在持续时间内的10轮内，他们会获得等同于步行速度的飞行速度。如果参与者在回合结束时没有站在水平面上，回合结束时就会倒地。\r\n宁静Restfulness。 每个参与者在法术持续时间内在对抗魅惑或陷入睡眠的法术或其他魔法效应时具有优势。",
