    "description": "雷鸣般的巨声于法术持续时间内回响在源自你的半径10尺的光环区域。每当光环区域进入一名你可见生物所在的空间时、一名你可见的生物进入光环区域或是在该区域结束其回合时，该生物都要进行一次体质豁免检定。失败则该生物受到3d6雷鸣伤害且陷入耳聋状态，持续至你的下一回合开始。豁免成功则仅受半伤。一名生物一回合只进行一次该豁免。你在施展该法术时可以指定哪些生物不受其影响。\r\n此外，你获得对雷鸣伤害的抗性，且对你发动的远程攻击检定均具有劣势。\r\n升环施法。你使用的法术位每比三环高一环，法术的伤害就增加1d6。",
