    "duration": "专注，至多1分钟",
    "description": "你选择施法距离内一点为中心，半径10尺球状区域内的每名生物必须成功通过一次感知豁免，否则目标不能执行反应和附赠动作，并且必须在其每个回合开始时掷1d10，根据下表内容来决定当回合的行为。\r\n\r\n1d10 当前回合行为 \r\n1 目标不执行任何动作，并使用所有移动力来进行移动。掷 1d4 决定其方向：1.北、2.东、3.南、4.西。 \r\n2~6 目标不进行移动也不执行任何动作。 \r\n7~8 该生物不进行移动，执行动作来对其触及内一名随机生物发动一次近战攻击。如果没有生物在其触及内，则目标本回合不执行任何动作。 \r\n9~10 该生物自行决定当回合行为。受影响的目标在其每回合结束时都可以重新豁免，豁免成功则结束其身上该法术的效应。 \r\n\r\n升环施法： 使用的法术位每比四环高一环，此法术的球状区域半径就增加5尺。",
