    "duration": "专注，至多10分钟",
    "description": "你在持续时间内将许多自然精魂咒唤在你身周10尺光环区域内。每当光环区域进入一名你可见生物所在的空间时、一名你可见的生物进入光环区域或是在该区域结束其回合时，你都可以迫使该生物进行一次感知豁免检定。失败则该生物受到5d8点力场伤害，成功则只受一半伤害。一名生物一回合只需要进行一次该豁免。\r\n此外，在持续时间内，你能够以附赠动作执行撤离动作。\r\n升环施法：使用的法术位每比四环高一环，此法术的伤害就增加1d8。",
