    "description": "你将传送至施法距离内的一处地点。你会准确到达该目的地。法术的目的地可以是你能看见的、可想象的地点，也可以是通过距离和方向说明的地点，比如“径直向下200尺”，“西北偏上45度300尺”。\r\n你还可以带上一名自愿生物一同传送。该生物在你传送时必须距你5尺内，且其传送终点也位于你所选目的地的5尺内。\r\n如果你、你携带的生物、或两者均将被传送至一处已被一名生物占据、或被一个或更多物件填满的空间中，则你和任何与你一起传送的生物都将受到4d6点力场伤害，且传送失败。",
