    "duration": "10分钟",
    "description": "轻薄缥缈的火焰在法术持续期间环绕着你的身体，散发出10尺半径的明亮光照和额外10尺的微光光照。\r\n这层火焰可以为你提供一面温暖护盾或冻寒护盾，由你选择。温暖护盾将赋予你对冷冻伤害的抗性，而冻寒护盾则会赋予你对火焰伤害的抗性。\r\n此外，每当一名距你5尺内的生物以一次近战攻击命中你时，这个护盾将迸发出火焰。温暖护盾将对攻击者造成2d8点火焰伤害，冻寒护盾将对攻击者造成2d8点冷冻伤害。",
