    "description": "一道冷冽光芒在法术持续时间内缭绕你身，散发出20尺半径的明亮光照和额外20尺的微光光照。\r\n直到法术结束，你具有光耀伤害的抗性，并且你的近战攻击在命中时额外造成2d6点光耀伤害。\r\n此外，在你受到距你60尺内一名你可见的生物的伤害后，你可以立即用一个反应，强迫其进行一次体质豁免。豁免失败者直到你的下个回合结束为止陷入目盲状态。",
