    "material": "一条皮带",
    "duration": "1小时",
    "description": "你触碰一个自愿生物，并使目标在法术持续时间内移动时不受困难地形限制，并且任何法术或其他魔法效应都不能降低目标的速度，或者使目标陷入麻痹或束缚状态。目标还会获得等同于其速度的游泳速度。\r\n此外，该目标还可以花费5尺移动力直接从非魔法的束缚物中挣脱（诸如镣铐或其他生物对其施加的受擒状态）。\r\n升环施法：使用的法术位每比四环高一环，你就可以额外再指定一名生物作为此法术的目标。",
    "classes": "吟游诗人、牧师、德鲁伊、游侠、奇械师、药剂师",
