    "duration": "直至解除",
    "description": "你将一个箱子及其内容物藏在以太位面。你必须同时接触箱子和作为法术材料成分的微缩模型。箱子最多可容纳12立方尺的非活体物质（3×2×2 尺）。\r\n箱子处于以太位面时，你可以用一个魔法动作并触碰箱子的模型来召回箱子。箱子出现在你 5 尺内一个未被占据空间的地面。随后，你可以使用一个魔法动作并同时触碰箱子与微缩模型来把箱子送回以太位面。\r\n60日之后，法术的效应会每日累计5%的概率自动结束。如果你再次施展该法术或箱子的模型被摧毁，该法术的效应也将随之终止。如果法术终止时箱子处于以太界，则其留在那里等待被你或者其他人找到。",
