    "duration": "专注，至多1小时",
    "description": "你点名或描述一个你熟悉的生物。只要该生物与你相距不超过1000尺，你就会感测到该生物的方位。如果该生物正在移动，则你也将知晓其移动的方向。\r\n该法术可以定位一个你认识的特定生物；或者它也可以定位特定的一类生物（例如人类或独角兽）中距你最近的个体，不过你需要曾经在 30 尺的近距离内看到过该类生物至少一次。如果被点名或描述的生物并不处于其原本的形态（例如正被一个变形术Polymorph或石化术Flesh to Stone的法术效应影响），则该法术无法定位该生物。\r\n如果有任意厚度的铅，即使只是薄薄一片铅片阻挡了你与被定位物件间的通路，则该生物也无法被该法术所定位。",
