    "material": "",
    "duration": "专注，至多1分钟",
    "description": "你指定施法距离内一名你可见的生物，窥探其噩梦，依此创造一道只有目标能看见的幻象。目标生物进行一次感知豁免。豁免失败时，目标受到4d10点心灵伤害，且在法术持续时间内进行的所有属性检定与攻击检定都具有劣势。豁免成功，则目标只受一半伤害，法术终止。\r\n法术持续时间内，目标在其每回合结束时进行一次感知豁免，豁免失败将再次受到心灵伤害。豁免成功则法术终止。\r\n升环施法：使用的法术位每比四环高一环，此法术的伤害就增加1d10。",
    "classes": "吟游诗人、法师",
