    "description": "你从未来的自己处接收到一条最多6个单词的讯息，警告你即将面临的重大威胁，或指引你走向一条有望收获成果的道路。这条信息由DM决定。在未来的某个时刻，一旦你理解了自己为何发送这条讯息，你必须进行一次长达10分钟的仪式（可在短休或长休期间进行），将这条讯息送回过去传达给现在的你。若你施展该法术时未收到任何讯息，这意味着你在未来永远不会完成这个仪式——这可能是因为你的死亡，亦或遭遇了其他阻碍。\r\n一旦你施展了此法术，在七天内或直到你完成仪式前，你都不能再次施展它。",
