    "description": "你发出一声原始的嚎叫，召唤低等生物听从你的命令。当你施展此法术时，源自你的100尺光环区域内的每个野兽都必须进行一次感知豁免。若豁免失败，则目标陷入魅惑状态，能够理解你的命令，并且在其下一回合内尽可能地遵循这些命令。在你的随后回合内，你可以使用魔法动作下达新的命令。若豁免成功，则目标陷入魅惑状态，直至你的下一回合开始，但是你无法进一步命令它。该嚎叫最远300尺内都能听见。",
