    "description": "你为你触碰的武器注入炼狱的祝福。直到法术结束之前，武器都会熄灭半径30尺内的任何普通*光源。此外，用这把武器命中时会造成额外2d6暗蚀伤害。如果该武器原先是非魔法武器，则在法术持续时间内其将暂时转变为魔法武器。\r\n持握此武器期间，在你自己的回合中以一个附赠动作，你可以提前结束这个法术并使武器迸发黑暗能量。每个位于武器30尺内由选择的生物必须进行一次感知豁免检定。豁免失败则生物将受到4d6暗蚀伤害，并陷入恐慌，持续1分钟。豁免成功则只承受一半伤害并不会陷入恐慌。陷入恐慌的生物在其每个回合结束时重复豁免，成功则终止其身上的该效应。",
