    "description": "在此法术的持续时间内，当你下次使用近战武器攻击一个生物时，你的武器会击碎该生物周围环境的魔法。攻击会造成额外4d6力场伤害。如果该生物正在专注法术，专注会被打破。此外，目标身上任何三环或三环以下的法术都会终止。对于目标身上的每个四环或更高的法术，使用你的施法属性进行一次属性检定。DC等于 10+法术环阶。检定成功时，法术结束。",
