    "material": "",
    "duration": "立即（特殊，见正文）",
    "description": "你号令温和的自然魔法来改变植物的生长。你可以在5尺的立方区域内看到的任何植物都可以呈现出你想要的任何形状。此外，如果植物是荆棘或能够生长荆棘，你可以将受影响的范围变成困难地形。\r\n在你改变的地形内，目标每移动5尺将受到2d4穿刺伤害。\r\n你也可以增加或减少由你产生的任何形状的植物的花、藤、叶、刺、枝、果实的数量。\r\n一小时后，你的魔法消失，植物恢复正常形状。如果你能使用法术植物交谈 Speak with Plants（或类似的能力）来与植物交流，你也许能会说服它保留其新的形式。不同的植物有不同的情感和态度。\r\n如果变形后的形态与它自然的形态大保留不相符，它保留该形态的兴致会下降。若植物同意，在dm决定下，它将保留该形态。在这种情况下，该法术将造成永久效果。\r\n升环施法。当你使用5环或更高环阶的法术位施展该法术时，你使用的法术位每比4环高一环，就可以多5立方尺影响范围。",
