    "components": "V/S",
    "material": "",
    "duration": "1分钟",
    "description": "你创造出两颗围绕你运转的小星星。它们会在以你为中心的10尺范围内散发出微光光照。星星会保护你，如果你周围5尺内的生物以近战攻击命中你，它必须成功进行一次感知豁免，否则每颗环绕你的星星都会对其造成 1d8的光耀伤害。\r\n每回合一次，在你的回合里，你可以使用你的动作使一颗星星向敌人飞去，让它在刺眼的闪光中爆炸并消耗它的能量。你对120尺内一敌人进行一次远程法术攻击，命中造成 4d8的光耀伤害，然后目标必须成功进行一次体质豁免，否则会陷入目盲，直到你的下一回合开始。\r\n当法术持续时间结束、你陷入昏迷或者你耗尽了所有的星星时法术结束。\r\n升环施法。当你使用5环或更高环阶的法术位施展该法术时，每比4环高1环，你便可额外创造一颗星星，每增加一颗星星会令以你为中心的微光光照半径增加5尺。",
    "classes": "德鲁伊、游侠、术士、法师",
