    "duration": "专注，至多10分钟",
    "description": "你唱着尖利的曲调，将暗影编织成一张巨大的、不断增长的网。\r\n你选择施法距离内一点，该区域20尺立方的区域充满了暗影，该区域被轻微遮蔽，并为里面的任何生物提供了半身掩护。你可以在专注期间每一轮在施法距离内创造一个新的立方体，在这种情况下，前一个立方体在1轮后消失。立方体可以重叠，但效果不会叠加。\r\n每个进入该区域或在该区域开始其回合的生物必须进行一次敏捷豁免。豁免失败时，除非它停留在该区域或者检定成功否则就会陷入失能。因此失能的生物每轮可以进行一次力量检定对抗你的法术豁免DC，检定成功则不再失能。\r\n昼明术Daylight可以移除一处单一的20尺立方体暗影。",
