    "duration": "专注，至多10分钟",
    "description": "随着噼啪作响的闪电，你传送到120尺内的一处可见未占据空间，距离你离开的起点和目的地5尺内的每个生物都必须进行一次敏捷豁免，豁免失败者受到1d12点闪电伤害，豁免成功伤害减半。\r\n在法术持续时间内你的每个回合里，你都可以使用附赠动作唤起闪电并再次这样打开风暴之门，但每次都要选择不同的地点为目的地。如果你在户外施法，风暴会在一分钟内逐渐发展并跟随你，在这种情况下，法术的伤害会增加到2d12，你可以至多传送240尺。\r\n升环施法。当你使用五环或更高环阶的法术位施展此法术时，你可以选择距离你5尺内的一个生物与你一同传送。同行的生物不会受到闪电伤害。",
