    "duration": "立即",
    "description": "你怂恿邪魔攻击远方的敌人。在提供祭品后，进行一次法术攻击检定以确定召唤哪个邪魔：\r\n\r\nD20 结果 CR \r\n1-4 献祭失败 —— \r\n5-8 风魔Wind Demon（见《生物抄本Creature Codex》）或小恶魔Quasit  1-2 \r\n9-12 鼠疴魔Rattok Demon（见生物抄本）或须魔Bearded Devil  3-4 \r\n13-16 次级月魔Lesser Lunar Devil（见第九章）或鹫魔Vrock  4-6 \r\n17-20 月魔Lunar Devil（见万兽图志）或狂蟾魔Hezrou  8 \r\n21+ 阿尔奈蛇魔Alnaar（见生物抄本）或角魔Horned Devil  9-11 \r\n\r\n\r\n召唤后，你必须强迫邪魔寻找你选择的与你处于同一位面的特定生物。 你必须通过一次DC10的魅力（游说）检定。 成功后，邪魔就会悄悄溜到它的目标处，通常但不总是在晚上。如果检定失败，邪魔会拒绝，祭品和碗会在施法过程中消耗掉。 \r\n召唤出的邪魔可能会发现目标被守护、无法接近或根本难以找到 （无论是因为隐形还是其他原因）。在这种情况下，你必须进行一次DC15的魅力 （游说）检定，如果成功，邪魔会返回以报告失败，不再要求献祭然后消失。 如果检定失败，邪魔会返回并要求你再次献祭。 如果没有立即献祭，它就会攻击你。",
    "classes": "牧师、德鲁伊、术士、法师",
    "source": "黯潮之书"
