    "description": "你召唤出一个传送门或门道，将施法距离内一处可见未占据空间与物质位面或妖精领域fey realms中的精确位置--如米德加德、影域Shadow Realm或盛夏之地Summer Lands——一个你曾经待过的地方。传送门是一个半圆形的开口，直径在5到20尺之间，甚至可以是大树的树根或树枝下。你可以将入口朝向你选择的任何方向。在它出现的每个位面上都有正面和背面。 穿越传送门只能通过它的正面。 这样做的任何东西都会立即传送到另一个位面，出现在离传送门最近的未占据空间里，传送门会持续很长一段时间。\r\n神祗和其他位面统治者可以阻止此法术创建的传送门在他们面前或在其领域内的任何地方开启。\r\n升环施法。当你用五环或更高环阶的法术位施展该法术时可以使传送门在创建后持续一周，如果使用六环级或更高法术位施展的传送门是永久的，直到用法术光耀信标Radiant Beacon（见下文）或祈愿术Wish 解除。",
