    "description": "毁灭能量从你身上扩散而出，覆盖了30尺光环范围。光环范围内你选择的每个生物进行一次体质豁免。豁免失败者受到5d6点雷鸣伤害和5d6点光耀或暗蚀伤害（由你选择）并且陷入倒地状态。豁免成功只受一半伤害。",
