    "material": "一撮硫磺",
    "duration": "立即",
    "description": "一支辉煌火焰的立柱从上方呼啸着降落。位于以施法范围内一点为中心，半径10尺、高40尺柱状区域内的每个生物必须进行一次敏捷豁免。豁免失败者将受到5d6点火焰伤害和5d6点光耀伤害，豁免成功则只受到一半伤害。\r\n升环施法：使用的法术位每比五环高一环，其火焰伤害和光耀伤害就均增加1d6。",
