    "description": "你触碰一名生物并魔法性地移除目标身上的下列效应之一：\r\n　　• 1级力竭\r\n　　• 魅惑或石化状态\r\n　　• 一道诅咒，包括目标因与一件被诅咒魔法物品的同调所陷入的诅咒。\r\n　　• 目标某项属性值的减损\r\n　　• 目标生命值上限的降低",
