    "description": "你指定施法距离内一点，并以该点为中心使半径 20 尺球状区域内堆满成群的噬人蝗虫。虫群使整个区域成为困难地形并处于轻度遮蔽，在法术终止前都会持续存在。\r\n当虫群显现时，区域内的每个生物都必须进行一次体质豁免，豁免失败则受到4d10穿刺伤害，成功则受到半数伤害。生物在一个回合内第一次进入该区域内，或者在区域内结束其回合时，也必须进行该豁免。一名生物每回合仅需进行一次该豁免。\r\n升环施法： 使用六环或更高法术位施展该法术时，你使用的法术位每比五环高一环，伤害就增加1d10。",
