    "duration": "专注，至多1分钟",
    "description": "你以施法距离内你能看到的一点为中心，创造出一场闪光和雷鸣交织的风暴，席卷10尺半径、40尺高度的柱状区域。在这片区域内，生物会陷入目盲和耳聋状态，并且不能施展任何含有声音成分的法术。\r\n当风暴出现时，任何处于其中的生物都必须进行一次体质豁免，豁免失败则受到2d10点光耀伤害与2d10点雷鸣伤害，豁免成功受到半数伤害。生物在一个回合内首次进入该区域内，或者在区域内结束其回合时，也必须进行该豁免。一名生物每回合仅需进行一次该豁免。\r\n升环施法：使用的法术位每比五环高一环，此法术的光耀和雷鸣伤害都回增加1d10。",
