    "material": "价值250+GP的熏香，作为法术耗材。以及每块价值50+GP的四块象牙板",
    "duration": "立即",
    "description": "点名或描述一个著名的人物，地点，或物件。该法术在你脑海中形成一段由DM描述的关于该事物重要传闻的简单概述。\r\n这些传闻可能包括了重要的细节，有趣的揭秘，也可能是不曾被广泛知晓的秘闻。你掌握目标越多的信息，所得到的信息就越精确细致。你由此得到的信息必定是准确的，但仍可能会以比喻或诗歌来表达，具体将由DM决定。\r\n如果你选的事物其实并不著名，你会听到仿佛由长号演奏而出的悲伤的音符，随后法术失败。",
