    "description": "一道治愈能量从施法距离内你指定的一点涤荡而出。你在该点周边30尺半径的球状区域内指定至多六个生物，并使每个目标生物恢复 5d8+你的施法属性调整值 点生命值。\r\n升环施法：使用的法术位每比五环高一环，法术的治疗量就增加1d8。",
