    "material": "价值1000GP+的珍稀油，作为法术耗材",
    "duration": "立即",
    "description": "你触及一名类人生物的遗体或遗体的一部分。若该生物死亡时间不超过10日，则法术会创造出一具新的成年身体，并呼唤该生物的灵魂进入此新身躯。骰1d10，然后参照下表来决定新躯体的种族，或者DM也可以选择其他可选种族。\r\n\r\n1d10 种族  1d10 种族 \r\n1 阿斯莫  6 歌利亚 \r\n2 龙裔  7 半身人 \r\n3 矮人  8 人类 \r\n4 精灵  9 兽人 \r\n5 侏儒  10 提夫林 \r\n若种族描述中提供了可选选项，则由被转生的生物做出选择，且其保留其前生记忆。目标保留原形的一切能力，不过其种族特质将以新种族的相应特质做更替。",
    "classes": "德鲁伊",
    "source": "玩家手册"
