    "components": "V/S",
    "material": "",
    "duration": "8小时",
    "description": "你选择施法距离内你能看见的任意数量生物，为他们提供一个虚假外观。不愿意受该法术影响的目标可以进行一次魅力豁免，豁免成功则不受该法术影响。\r\n你可以为不同目标提供同样或不同的外观。法术能改变生物的身体和装备外观。你可以让目标看起来身高有 1 尺的增减，看上去更轻或更重。目标的新形貌的肢体结构必须与目标原形相符，但你可以随意改变其他的外观特征。法术会持续至时间结束。\r\n此法术产生的变化无法应对物理检查。比如，你用此法术为一个生物添了一顶帽子，那么现实物件会穿过帽子。\r\n一个使用研究动作来检查目标的生物可以进行一次智力（调查）检定来对抗你的法术豁免DC。如果它成功了，它会意识到目标进行了伪装。",
    "classes": "吟游诗人、术士、法师",
