    "material": "",
    "duration": "立即",
    "description": "选择施法距离内的一点，你引爆其间的心灵能量。以那一点为中心，半径20尺球状区域内的每个生物进行一次智力豁免检定。豁免失败的生物受到8d6心灵伤害，成功则只受到一半伤害。\r\n豁免失败的目标还会在接下来的1分钟内思想混乱。在此期间，目标每次进行攻击检定、属性检定和为维持专注而进行体质豁免检定时都获得一枚d6的减值。在目标的每个回合结束时它都可以重新进行智力豁免检定，若成功将结束这个效应对自己的影响。",
