    "description": "• 你向距离内一个可见生物发出丝带状的负能量。如果目标不是不死生物，他必须进行一次体质豁免检定，并在豁免失败时受到5d12点黯蚀伤害，若豁免成功则只承受一半。被这个伤害杀死的目标将在你的下回合开始被唤起为一只僵尸zombie。僵尸会追杀距离他最近的、他可以看见的任何生物。僵尸的数据参考怪物图鉴。\r\n• 如果你以不死生物作为目标使用该法术，目标不需要进行豁免检定，取而代之的是目标得到5d12的一半作为临时生命。",
