    "material": "",
    "duration": "专注,至多1分钟",
    "description": "• 你唤醒自然界的精魂对抗你的敌人。选择施法距离内你可见的一点，精魂令那一点为中心60尺立方区域内的树木、岩石和草丛被活化，直到法术结束。\r\n• 草丛和灌木Grasses and Undergrowth：立方区域内被草丛或灌木覆盖的地面对你的敌人而言是困难地形。\r\n• 树木Trees：在你的每个回合开始，在立方区域内的任何树木周围10尺范围内的每个你的敌人都必须成功进行敏捷豁免检定，否则会因为树枝的挥打受到4d6挥砍伤害。\r\n• 根与藤Roots and Vines：在你的每个回合结束时，立方区域内站于地面上的一个你选择的生物必须成功进行力量豁免检定，否则会被束缚直到法术结束。被束缚的生物可以使用它的动作来进行一次力量（运动）检定对抗你的施法DC，如果成功将会结束这个效果对自己的影响。\r\n• 投石Rocks：在你的回合中以一个附赠动作，你可以使一块立方区域中的松动岩石投掷向同样在区域里的一个你可见的生物。若击中，目标受到3d8非魔法钝击伤害，并且必须成功进行力量豁免检定否则应击倒地。",
    "classes": "德鲁伊、游侠",
    "source": "珊娜萨的万事指南"
