    "material": "",
    "duration": "专注,至多1分钟",
    "description": "每名目标必须成功通过一次敏捷豁免，否则将在持续时间内受到此法术影响。受影响的目标在其每个回合开始时受到4d6挥砍伤害，且其攻击和属性检定具有劣势。若目标试图移动，其必须进行一次体质豁免，失败则陷入倒地并再受到受惊猫咪的2d6挥砍伤害。受影响生物回合结束时，进行另一次敏捷豁免，成功则结束其身上的此法术效应。\r\n升环施法。使用六环或更高法术位施展该法术时，你使用的法术位每比五环高一环，受影响目标回合开始时受到的伤害就增加2d6。",
