    "description": "风，环绕着你的躯体，卷起你的头发和衣摆，并将你的双脚托到空中。你获得60尺飞行速度。此外，你为避免被 擒抱Grappled 所作的属性检定，以及避免陷入 束缚Restrained 或 麻痹Paralyzed 所作的豁免检定具有优势。\r\n法术效应期间，若你被选为一道法术或一次攻击的目标，你可以用你的反应传送到至多60尺外的一处未被占据的空间内。如果此行动使你脱离了该法术或该攻击的范围，你便不会受其影响。传送结束后，本法术会立刻结束。",
