    "duration": "专注，至多10分钟",
    "description": "你选择施法距离内最多六个你能看见的生物或物体，使其垂直升起最多20尺，并在法术持续时间内悬浮于空中。此法术可以使重量不超过500磅的目标浮空。非自愿的生物若通过体质豁免则不受影响。\r\n目标只能通过推拉触及范围内的固定物体或表面（比如墙壁或天花板）来移动，如同在攀爬一般。在你的回合中，你可以在20尺之内改变任意数量目标的高度。如果你是其中一个目标，作为移动的一部分，你可以将目标上下移动。否则，你可以使用你的动作移动这些目标，但目标必须始终保持在施法距离内。\r\n当法术结束时，仍在空中的目标会缓慢飘落至地面。",
