    "duration": "立即",
    "description": "在施法距离内你可见的一点，一个巨型南瓜灯迅速生长而出。它可以容纳该点为中心、半径5尺范围内的生物。你可以选择让它容纳范围内最多四个中型或更小的生物，或者一个大型生物。任何不愿被困入南瓜灯中的生物可以进行一次敏捷豁免检定，若检定成功，该生物可以迅速跳离5尺距离，避开南瓜灯的包裹。\r\n在南瓜灯内的生物只能通过你施法时选定的一侧上的眼睛和嘴巴观察外界。生物只能从这一侧使用远程或触及武器进行攻击。南瓜灯外的生物透过其嘴巴或眼睛往里看时，只能看到温暖的发光。在南瓜灯存在期间，无论南瓜灯内外的生物都无法穿过它。\r\n南瓜灯重5,000磅，AC为15，具有100点生命值。南瓜灯每年自然损失20点生命值。当南瓜灯生命值降至0时，它会被摧毁。",
