    "duration": "专注，至多1分钟",
    "description": "你创造了一个能干大事的生物，就像一名故事书中的勇士，同时让该生物的敌人值得英雄关注。你选择施法距离内一生物，在法术持续时间内，其在所有属性检定、攻击和豁免上具有优势。同时，攻击你目标的生物，或对源自你目标的法术或其他效应进行豁免的生物具有优势。非自愿目标需进行一次魅力豁免抵抗该效果。\r\n升环施法。当你用七环或更高环阶的法术位施展该法术时，每比六环高一环，便可额外增加一个生物为目标。",
    "classes": "吟游诗人、牧师、圣武士",
