    "duration": "专注，至多10分钟",
    "description": "你讲述的故事蜿蜒曲折，充满了旁白和离题，以至于听众都不知道故事的重点在哪里。任何陷入耳聋或无法被魅惑的生物都免疫此法术的效果。\r\n你选择距离你20尺内任意名生物，他们被迫停下手中的工作，聆听你的故事。当他们被你的话所吸引时、它们会在智力（调查）和感知（洞悉和察觉）检定中自动失败，且他们在这些技能上的被动检定结果会变为0。生物可以选择离开你的表演，但必须先通过一次感知豁免，否则会陷入昏迷1分钟。如果你失能或不再说话，此法术就会终止。",
    "classes": "吟游诗人、魔契师",
    "source": "黯潮之书"
