    "description": "月光从天而降，在持续时间内以微光光照笼罩源自你的20尺光环区域。你和你的盟友在位于该区域期间获得半身掩护及对寒冷、闪电及光耀伤害的抗性。\r\n在法术持续时间内，你可以使用以下选项之一（但这将令此法术立即结束）：\r\n解放Liberation。当你失败于一次用于避免或结束恐慌、受擒及束缚的豁免时，你可以用一个反应来将本次豁免改为成功。\r\n回春Respite。以一个魔法动作，你或区域内的一名盟友恢复等于4d10+你的施法属性调整值点生命值。",
