    "description": "你将来自妖精荒野的中型精魂咒唤在施法距离内一处你可见的未占据空间中。精魂在持续时间内一直存在，其外貌看起来像是一名你选择的妖精生物。当精魂显现时，你可以对位于精魂5尺内的一名生物进行一次近战法术攻击。命中则目标受到等于3d12加你施法属性调整值总和的心灵伤害，并且直到你的下个回合开始为止，目标处于恐慌状态，你和精魂均是目标的恐惧源。\r\n在后续的你的回合中，以一个附赠动作，你可以将精魂传送至一处位于其原位置30尺内的你可见的未占据空间，并对位于精魂5尺内的一名生物进行上述攻击。\r\n升环施法： 使用的法术位每比六环高一环，法术造成的伤害就增加2d12。",
