    "castingTime": "10分钟",
    "range": "自身",
    "components": "V/S/M",
    "material": "一尊价值1500+GP的饰宝石自塑像",
    "duration": "10日",
    "description": "选择一道五环或以下的你能够施展的法术，其施法时间需为动作且能够以你为目标。这道法术被称为凭依法术。你作为施展触发术的一部分施展凭依法术，同时消耗凭依法术与触发术的法术位，但凭依法术并不会立即生效，而是在满足特定触发条件时才生效。你在施展这两道法术的时候描述触发条件。例如，触发术与水下呼吸Water Breathing 一起施展可以确保水下呼吸在你被水或类似液体淹没时触发其效应。\r\n凭依法术的效应在相应状况第一次出现时立即生效，而无论你是否想要这么做，在那之后触发术随即终止。\r\n凭依法术的效应只能作用于你，哪怕它通常可以指定其他目标也无法再作指定。你同一时间只能使用一道触发术。如果你再次施展该法术，则你身上前一道触发术的效应立即终止。另外，当触发术的材料成分不在你身上时，你身上的触发术效应也将立即终止。",
