    "description": "一个固定的微光屏障在你周围10尺光环范围内出现并在法术持续时间内维持存在。\r\n任何在屏障外施放的五环或更低环阶的法术无法影响其内的任何东西。此类法术能够以屏障内的生物或物件为目标，但无法对其生效。同样的，屏障内区域也将被排除在此类法术所创造的效应区域之外。\r\n升环施法：使用的法术位每比六环高一环，屏障能阻挡的法术就高一环。",
