    "description": "你咒唤一场盛宴出现在你周围地面上未被占据的10尺立方空间。盛宴需要1小时来享用，并会在这段时间结束后消失不见，而且下述增益效应在这1小时结束前不会生效。你可以让至多十二个生物一同分享盛宴。\r\n所有享用了大餐的生物都会获得几种增益。这些生物获得毒素伤害的抗性、中毒状态免疫与恐慌状态免疫，他们的生命值上限也将提高2d10点（并获得等量的生命值）。这些增益将持续 24 小时。",
