    "description": "你在身体周围创造出一个巨大的虚体甲壳，它能保护你并在战斗中助你一臂之力。在持续时间内，你的护甲等级变为20（若原本不高于此值），获得40尺游泳速度，以及30尺范围内的盲视。此外，你可以使用附赠动作用你的钳子进行一次近战武器攻击。此攻击使用你的法术攻击加值，命中时造成1d10点钝击伤害。\r\n另外，你的虚体甲壳拥有15点的伤害阈值。伤害阈值使你免疫所有未达到阈值的伤害，只有等于或大于阈值的伤害才能正常对你造成伤害。任何未达到甲壳伤害阈值的伤害都被视为浅层伤害，不会减少任何生命值。",
    "classes": "术士、法师",
    "source": "胧忆岛：蒿野物语"
