    "material": "一块旗帜碎片",
    "duration": "立即",
    "description": "你唤起众多已逝骑士之精魂，从你所在之处向前冲锋，形成一条90尺长、20尺宽的线状区域，随后消失。该线状区域内每个你选择的生物都必须进行一次感知豁免。若豁免失败，则目标受到5d12暗蚀伤害，陷入恐慌状态，直至你的下一回合开始，并且其必须立即使用反应（若可用），以最安全的路线尽可能远离你。若豁免成功，则该生物仅受到一半伤害。 \r\n升环施法。使用的法术位每比六环高一环，伤害就增加1d12。",
