    "description": "一顶圣光燃烧的王冠装饰在你的头上直到法术结束。任何移动进入你20尺内或在你20尺内开始回合的邪魔、妖精或亡灵受到2d8光耀伤害。\r\n光耀冠冕会在其半径30尺内提供明亮光照并在该范围外30尺提供微光光照。",
