    "material": "",
    "duration": "立即",
    "description": "你向施法距离内的一个可见生物释放负能量。该生物必须进行一次体质豁免。豁免失败则受到7d8+30点暗蚀伤害，豁免成功则伤害减半。\r\n被该法术杀死的类人生物将在你下一回合开始时被唤起为一只受你操控的丧尸Zombie（见附录B），并在随后尽力遵循你的口头指令。",
    "classes": "术士、魔契师、法师、药剂师",
