    "material": "",
    "duration": "立即",
    "description": "一片烈焰风暴出现在施法距离内。风暴的区域由至多十个10尺立方区域组成。你可以自行安排各立方区域的组合方式。每个立方区域必须至少与一个其他的立方区域相连。区域内每个生物必须进行一次敏捷豁免。豁免失败者将受到7d10点火焰伤害，豁免成功则伤害减半。\r\n区域内所有未被着装或携带的可燃物件会开始燃烧。",
