    "description": "你和至多八名手牵着手形成一个圆圈的自愿生物被输送到一个不同的存在位面。你可以概括地指名一个目的地，比如火元素位面Plane of Fire的黄铜之城City of Brass，或九层地狱Nine Hells第二层迪斯帕特Dispater 的宫殿，按照DM的判断，你将出现在目的地里或其附近。\r\n另外，如果你知道某个处于另一位面的传送法阵的印记序列，则该法术可以把你带到该法阵处。如果该传送法阵太小而装不下所有你输送的生物，则他们会出现在离传送法阵最近的未占据空间中。",
