    "description": "• 两个施法距离内的你能看见的生物必须进行一次体质豁免，若两者在30尺内，则他们的豁免检定具有劣势。每个生物都能自愿放弃豁免。若两者中有一个豁免成功了，那么法术没有效果。若两人豁免均失败了，那么他们便会在法术持续时间内魔法般地被连接在一起，无论两人间距多少。 若其中一人受到伤害 ，另外一人也会受到等额的伤害。若其中一人恢复了生命值，另外一人也会恢复等额的生命值。\r\n• 如果被系结的双方中任意一方的HP减少到了0，那么该法术结束。该法术在任意一方身上结束时，另外一方的法术也结束。",
    "classes": "法师",
