    "duration": "专注，至多1分钟",
    "description": "你从手中显现的光之弓上射出一支天使之箭。对施法距离内的一个生物进行一次远程法术攻击。若命中，目标受到4d10点力场伤害，且直到法术结束前，它将对你选择的下列伤害类型之一变得易伤：强酸、寒冷、火焰、闪电、暗蚀、光耀或雷鸣。若该生物对所选伤害类型免疫，则在持续时间内改为具有该类型的抗性；若该生物对所选伤害类型具有抗性，则在持续时间内失去该抗性。",
    "classes": "吟游诗人、牧师、法师",
