    "material": "一块丝质手帕",
    "duration": "10分钟",
    "description": "此法术能将一片腐肉地变成一场充满力量的盛宴。在持续时间内，你选择的任意生物都可以食用任何生物的腐肉。当法术持续时间结束时，如果一个生物在整个持续时间内都吃了腐肉，其会恢复10d6点生命值，恢复一半已消耗的生命骰（至少1）。移除其一半的力竭等级（至少1）并获得完成一次短休的所有好处。生物必须在法术结束时通过一次体质豁免，否则陷入中毒1小时。\r\n升环施法。如果使用9环法术位施展该法术，受影响的生物会移除所有力竭等级并恢复所有消耗的生命骰。",
