    "duration": "专注，至多1分钟",
    "description": "一片充满了炽热灰烬的旋转烟云显现，并以施法距离内一点为中心的蔓延至半径20尺的球状区域。烟云区域被重度遮蔽。烟云会存在直至持续时间结束，或是直至被一阵强风（例如被造风术Gust of Wind 所创造）所吹散。\r\n烟云出现时，每个处在其内的生物都必须通过一次敏捷豁免，豁免失败者将受到10d8点火焰伤害，豁免成功则受到一半伤害。该球状区域移动至生物所占据的空间，或者生物进入球状区域内，或者生物在球状 区域内结束其回合时，该生物也必须进行该豁免。一名生物每回合仅需进行一次该豁免。\r\n在你的每回合开始时，烟云会向你指定的、远离你的方向直线移动10尺。",
