    "material": "",
    "duration": "专注，至多10分钟",
    "description": "你将施法距离内一个你能看见的生物放逐到一个迷宫般错综复杂的半位面。目标将一直留在该处直至法术持续时间结束，或者直到它逃出该迷宫。\r\n目标可以使用研究动作尝试逃出迷宫。此时它可以进行一次DC20 （调查 ）的智力检定，检定成功将逃出迷宫，而该法术随之终止。\r\n法术终止时，目标将重新出现在它之前消失的位置。如果该位置被占据，则目标出现在最近的未占据位置。",
