    "ritual": false,
    "concentration": false,
    "castingTime": "动作",
    "range": "150尺",
    "components": "V/S/M",
    "material": "一块太阳石",
    "duration": "立即",
    "description": "指定施法距离内一点，以其为中心周围 60 尺半径的球状区域闪耀出灿烂的阳光。所有球状区域中的生物进行一次体质豁免。豁免失败者将受到12d6点光耀伤害，并陷入持续1分钟的目盲状态。豁免成功则仅受到一半伤害。\r\n因该法术陷入目盲的生物在其每回合结束时都可以再进行一次体质豁免。豁免成功则不再目盲。\r\n该法术将驱散法术区域内所有由法术所创造的黑暗。",
    "classes": "牧师、德鲁伊、术士、法师",
