    "description": "你只能在你所施展的法术神话通神术Contact Deity的持续时间内施展此法术。你使你所联络的神祇显现在最近的未占据空间。在1小时内，祂会按照自己的意愿行事，但只要你不对祂采取敌对行动，祂便会将你视为盟友。祂不会将此等礼遇延伸至你的盟友，且会将你为保护他人而进行的任何尝试都视为对祂的敌对行动。",
    "classes": "吟游诗人、牧师、德鲁伊、术士、魔契师、法师",
    "source": "火炬光下的克苏鲁"
