    "material": "一把手术刀",
    "duration": "专注，至多10分钟",
    "description": "你以施法距离一可见生物为目标，使用死灵之力割开它身上的皮肤。你对该生物进行一次远程法术攻击。被命中的目标必须通过一次体质豁免，否则会受到8d6暗蚀伤害，成功时伤害减半。在持续时间内的每个回合中，你都可以使用动作迫使同一目标再次进行体质豁免，并重复伤害。如果目标离开了法术范围，目标的生命值降为0，或目标对你而言被全掩护，法术也会终止。",
