    "duration": "专注，至多1分钟",
    "description": "你切断了目标之间的友谊和感情。你选择施法距离内两个可以看到你并听到你的生物。每个目标必须进行一次魅力豁免。豁免失败的目标必须使用其移动力和动作向该法术的另一个目标移动并攻击。如果一个未受该法术影响的目标移动到施法距离之外，另一个目标必须尽一切努力找到并攻击它。在目标每个回合结束时，若一个目标看不到另一个目标，则可以重复本豁免，豁免成功则解除控制。",
