    "description": "你短暂地停止其他所有人的时间流。你一次性进行1d4+1个回合，在此期间，时间对于其他生物而言是静止的，但你可以像正常一样移动和使用动作。\r\n在此期间，若你的一个动作或任何你创造出来的效应影响到除你之外的任何生物，或影响到其他生物着装或携带的物件时，法术将终止。此外，如果你在施法后移动到了距施法时位置1000尺以外的地方，则法术也将终止。",
