    "duration": "专注,至多1分钟",
    "description": "• 你以施法距离内你可见的一点为源点创造一个半径20尺的毁灭性球形力场。在法术持续时间内，球形力场与其100尺范围内的空间视为困难地形，且完全处于力场内的未被着装与携带的非魔法物件会被摧毁。\r\n• 当力场出现时或者在你的每回合开始时，力场的100尺范围内未被着装的物件将被直直拉向力场的中心，并在距离力场中心最近的未被占据的空间停止。\r\n• 当一个生物在力场的100尺范围内开始其回合时，其必须进行一个力量豁免，若失败则将被直直拉向力场的中心，并在距离力场中心最近的未被占据的空间停止。一个在当前回合内第一次进入力场的生物或在力场内开始其回合的生物会受到5d10点力场伤害并且被束缚，直到其离开力场范围。若力场位于空中，那么被束缚的生物将会在力场中悬浮。一个生物能以其动作进行一个对抗你的法术豁免DC的力量检定，若成功则能解除其自己或者另一个在其触及范围内的力场内的生物的束缚状态。若一个生物的HP被该法术降低至0，他与他身上携带的所有非魔法物件都会被湮灭。",
    "classes": "法师",
