    "description": "• 你选定一个施法距离内的目标，使他的身体形态受到飞速衰老的破坏。目标必须进行一个体质豁免并在豁免失败时受到12d10点黯蚀伤害, 或在豁免成功时只受到一半的伤害。若其豁免失败，目标还会快速老化至离老死只有三十天的时间点。在这个年龄段, 目标在攻击检定, 属性检定与豁免检定上承受劣势，其步行速度也减少一半。只有祈愿术Wish或以九环法术位施展的高等复原术Greater Restoration才能使这些效果消除并使其恢复原先的年龄。",
