    "description": "你创造出覆盖30尺锥状区域的湮灭能量，区域内每个浴血生物必须进行一次体质豁免。豁免失败者立即死亡，且连同其穿着和携带的非魔法物品一起化为灰尘。因此而死的生物只能通过完全复生术True Resurrection或祈愿术Wish 复活。",
