    "components": "V/S/M",
    "material": "一只瘟疫鼠的恶臭尸体",
    "duration": "立即",
    "description": "你使范围内你能看见的一个生物感染一种致命且有强传染力的疾病，这种疾病会在该生物身上始终持续，直到它被高等复原术Greater Restoration，医疗术Heal或许愿术Wish治疗。其他可以移除疾病的法术或魔法效果无法治愈此法术造成的传染病。\r\n被感染时，该生物必须在它的每个回合开始时进行一次体质豁免。若豁免检定失败则它需要承受10d8点黯蚀伤害，并且陷入失能状态直到它的下个回合开始。若豁免检定成功则其只承受一半伤害，且不会陷入失能。受感染的生物必须在它的每个回合开始进行豁免，直到它死亡或被治愈。\r\n一个在受此法术感染的生物身边10尺范围内开始回合的生物，其必须进行一次体质豁免。若豁免检定失败，则该生物也被感染。\r\n当你施展此法术时，你可以选择自己和至多八个其他生物免受此施展法术所带来的传染病的影响。",
