    "description": "对你5尺范围内的一个生物进行一次近战法术攻击。若命中，该生物将承受200点毒素伤害。此伤害无视该生物所拥有的毒素伤害的任何抗性或免疫，并且无法被任何方式减少或预防。\r\n这强有力的毒素会始终在目标体内徘徊并将其引至死亡。被此法术造成的毒素伤害减少生命值至0的目标，其自动在死亡豁免上失败，直到完成一次长休。对目标施展法术医疗术Heal和高等复原术Greater Restoration也可以结束此效果。",
